static int own_range(uint32_t address,size_t bytes){return (address>=SCREEN&&address-SCREEN<=SCREEN_SIZE&&bytes<=SCREEN_SIZE-(address-SCREEN))||(address>=VM_STACK&&address-VM_STACK<=1024&&bytes<=1024-(address-VM_STACK));}
