static void fill(nflstreet_team_player_window_side*x,unsigned side,unsigned salt){memset(x,0,sizeof *x);x->count=x->query_count=6;x->cursor=(int32_t)(salt%6)-1;x->mode=(int32_t)(salt%3);x->timer_word=0x65430000u|side<<8|salt;for(unsigned i=0;i<20;++i){x->rows[i].id=5000u+side*100u+salt*20u+i;x->rows[i].slot=(i<7&&i%3u==2u)?-1:(int32_t)i;x->rows[i].auxiliary=0x12340000u+i;x->query_ids[i]=x->rows[i].id;}}
static void write_addr(uint8_t*screen,uint32_t*words,uint32_t addr,uint32_t v){if(!memword(screen,words,addr,&v,1))abort();}
typedef struct {const nflstreet_team_player_window_side*x;unsigned side;int32_t query_index;uint32_t query_indices[4];unsigned query_calls,visibility_calls;uint32_t visible_index,visible_value;} services;
static int query_side(uint32_t a){return a==QUERY?0:a==QUERY+44?1:-1;}
static int32_t requested_index(const nflstreet_team_player_window_side*x,int32_t delta){int64_t v=(int64_t)x->cursor+x->mode;if(v<(int64_t)x->query_count)v+=delta;else v=v-(int64_t)x->query_count+delta-1;if(v< -1)v=(int64_t)x->query_count-1;else if(v>=(int64_t)x->query_count)v=-1;return (int32_t)v;}
