static void seed_game(uint8_t*ram,const nflstreet_team_player_window_side*x,unsigned side){put(ptr(ram,R13-0x5a34u+side*4u),x->count);put(ptr(ram,CURSOR+side*8u),(uint32_t)x->cursor);put(ptr(ram,CURSOR+side*8u+4u),(uint32_t)x->mode);uint8_t*rows=ptr(ram,ROSTER+side*0xf4u);for(unsigned i=0;i<20;++i){put(rows+i*12,x->rows[i].id);put(rows+i*12+4,(uint32_t)x->rows[i].slot);put(rows+i*12+8,x->rows[i].auxiliary);}put(ptr(ram,R13-0x6e1cu),x->timer_word);put(ptr(ram,R13-0x6e18u+side*4u),SENTINEL);}
static int setup_source(uint8_t*screen,uint32_t*words,unsigned owner,unsigned count,uint32_t descs[3],uint32_t scalar){memset(screen,0xa5,SCREEN_SIZE);for(unsigned i=0;i<256;++i)words[i]=SENTINEL;for(unsigned i=0;i<count;++i){uint32_t base=(owner&1u)?VM_STACK+32+i*32:SCREEN+32+i*32;descs[i]=base;write_addr(screen,words,base,2);write_addr(screen,words,base+4,7);write_addr(screen,words,base+8,2);write_addr(screen,words,base+12,SENTINEL);write_addr(screen,words,base+16,SENTINEL);}if(scalar){uint32_t v=SENTINEL;write_addr(screen,words,scalar,v);}return 1;}
