 uint8_t screen[SCREEN_SIZE];uint32_t words[256],descs[3]={0},scalar=0;unsigned arrays=property==0x8000000fu?3:1;setup_source(screen,words,owner,arrays,descs,0);scalar=(owner&2u)?VM_STACK+400:SCREEN+400;if(property==0x8000000fu){uint32_t v=SENTINEL;write_addr(screen,words,scalar,v);}
 nflstreet_ui_service_request q={0};q.kind=1;q.property=property;if(property==0x8000000fu){q.argc=5;q.args[0]=side;for(unsigned i=0;i<3;++i)q.args[1+i]=descs[i];q.args[4]=scalar;}else{q.argc=4;q.args[0]=side;q.args[1]=0xabcdef01;q.args[2]=(uint32_t)delta;q.args[3]=descs[0];}
