int main(int argc,char**argv){if(argc!=3)return 2;if(!guards()){fprintf(stderr,"Callback adapter invalid descriptor/overlap guard failed\n");return 3;}HMODULE h=LoadLibraryA(argv[1]);if(!h)return 4;ModernGekkoGetModuleFn get=(ModernGekkoGetModuleFn)GetProcAddress(h,MODERNGEKKO_GET_MODULE_SYMBOL);if(!get)return 4;const ModernGekkoModuleDesc*m=get();if(!m||m->cpu_state_size!=sizeof(CPUState))return 4;unsigned contexts[3]={14,15,16},checks=0;for(unsigned c=0;c<3;++c){char path[4096];int n=snprintf(path,sizeof path,"%s/position-neutral-%02u.mem1",argv[2],contexts[c]);if(n<0||(size_t)n>=sizeof path)return 5;size_t z=0;uint8_t*base=load_file(path,&z);if(!base||z!=RAM_SIZE)return 5;uint64_t hash=hash_bytes(base,z);for(unsigned side=0;side<2;++side){for(unsigned owner=0;owner<4;++owner){if(!original_case(m,base,side,0x8000000fu,owner,0,checks+1)||!original_case(m,base,side,0x80000010u,owner,-1,checks+2)||!original_case(m,base,side,0x80000010u,owner,1,checks+3)){fprintf(stderr,"context%u E9D4 callback case failed side%u owner%u\n",contexts[c],side,owner);free(base);return 6;}checks+=3;}}if(hash_bytes(base,z)!=hash){free(base);return 7;}printf("context%u: %u original E9D4/property callback comparisons passed; F/D outputs, lower PLAY-ID query ordinals, cursor/mode/timer and visibility matched; baseline FNV64 %016llx unchanged.\n",contexts[c],checks,(unsigned long long)hash);free(base);checks=0;}FreeLibrary(h);puts("Original 8011E9D4 properties8000000F/80000010 framing exact across three saved contexts; stack/screen array descriptor outcomes match the native adapter. DB getter outputs and visibility requests remain supplied lower boundaries.");return 0;}
